mod solution;

fn main() {
    let cases = [
    (r#"[5,7,7,8,8,10]"#, r#"3,4"#),
    (r#"[8]"#, r#"0,0"#),
    (r#"
[8]
"#, r#"0,0"#),
    (r#"  
[5,7,7,8,8,10]
  "#, r#"3,4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS first-last-position");
}
